"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65227"],{72144(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_abaixo_da_dependencia","status":422,"titulo":"O derivado protege menos que um fato que ele cita"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_abaixo_da_dependencia","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["Um fato derivado revela o que se sabe dos fatos de que depende: a regra padr\xe3o cita esses fatos, e o resumo de grupo re\xfane as respostas ao fato de membro. Por isso ele n\xe3o pode ter classifica\xe7\xe3o de prote\xe7\xe3o de dados mais fraca que a de nenhum deles. A escala vai do mais fraco ao mais forte: `PUBLICO`, `INTERNO`, `PESSOAL`, `IDENTIFICADOR`, `SENSIVEL`. A recusa vale para:","- o cadastro do resumo de grupo (`POST /api/configuracao/admin/fatos-candidato/agregados`), contra o fato de membro, com `field` igual a `classificacaoProtecao`;\\n- a defini\xe7\xe3o das regras padr\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`), contra cada fato citado, com `field` igual ao \xedndice da regra, como `regras[0]`;\\n- a altera\xe7\xe3o da defini\xe7\xe3o do derivado ou do resumo de grupo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) e o aceite da recomenda\xe7\xe3o de ajuste (`POST /api/configuracao/admin/fatos-candidato/{id}/aceite-da-recomendacao`), contra o que o fato j\xe1 cita ou resume, com `field` igual a `classificacaoProtecao`.","No cadastro do resumo de grupo, a mensagem cita o c\xf3digo do fato de membro. Na altera\xe7\xe3o, s\xf3 conta a recusa que a mudan\xe7a causa: a que j\xe1 existia antes dela n\xe3o impede a altera\xe7\xe3o. Nada \xe9 gravado."],"comoResolver":["Eleve a classifica\xe7\xe3o do fato derivado at\xe9 a do fato mais protegido que ele cita ou resume, ou tire a cita\xe7\xe3o da regra. A prote\xe7\xe3o do fato de que ele depende tamb\xe9m pode ser revista, mas isso muda o dado de origem e passa pela aprova\xe7\xe3o da prote\xe7\xe3o de dados (UNI-REQ-0205). Para elevar a classifica\xe7\xe3o do derivado, altere a defini\xe7\xe3o dele (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`)."],"ondeAparece":["Cadastro de um fato do cat\xe1logo que resume respostas de grupo","Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo","Aceite da recomenda\xe7\xe3o de ajuste da prote\xe7\xe3o de dados de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);